values ('ap_physics_2', 9, '9.1', array['9.1']::text[], 'vocabulary', 'Gas pressure (kinetic theory)', 'The pressure a gas exerts on a surface is the sum of the perpendicular force components from its atoms'' collisions with the surface divided by the surface area, and pressure exists throughout the gas, not just at the boundary.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-2-reference-u9-u11-2026-10-10; candidate=ap_physics_2-u9-r1-002; ced=9.1.A.1.ii, 9.1.A.1.iii: "Pressure exists throughout the gas itself, not just at the boundary"')
