values ('ap_physics_2', 9, '9.3', array['9.3', '9.4']::text[], 'vocabulary', 'Heating and cooling', 'Heating is the transfer of energy into a system by thermal processes, and cooling is the transfer of energy out of a system by thermal processes.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-2-reference-u9-u11-2026-10-10; candidate=ap_physics_2-u9-r1-009; ced=9.3.A.1.i, 9.3.A.1.ii')
