values ('ap_physics_2', 9, '9.3', array['9.3']::text[], 'vocabulary', 'Thermal equilibrium', 'Thermal equilibrium is the condition in which no net energy is transferred by thermal processes between two systems in thermal contact with each other.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-2-reference-u9-u11-2026-10-10; candidate=ap_physics_2-u9-r2-001; ced=9.3.A.4: "Thermal equilibrium results when no net energy is transferred by thermal processes between two systems in thermal contact with each other."')
