insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_2', 9, '9.4', array['9.4']::text[], 'convention', 'Ideal gas has no internal potential energy', 'Atoms in an ideal gas do not interact via conservative forces and their internal structure is not considered, so an ideal gas has no internal potential energy and its internal energy is the sum of the atoms'' kinetic energies.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-2-reference-u9-u11-2026-10-10; candidate=ap_physics_2-u9-r1-016; ced=9.4.A.1.i: "an ideal gas does not have internal potential energy"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
