values ('ap_physics_2', 9, '9.6', array['9.6']::text[], 'convention', 'Entropy as a state function; maximum at equilibrium', 'Entropy depends only on the current state of a system, not how it got there, and is maximum when the system is in thermodynamic equilibrium.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-2-reference-u9-u11-2026-10-10; candidate=ap_physics_2-u9-r1-026; ced=9.6.A.2.ii, 9.6.A.2.iii: "Maximum entropy occurs when a system is in thermodynamic equilibrium"')
